<template>
 <div class="v2-stack">
  <nav class="v2-tabs" aria-label="Sezioni marketing"><button v-for="tab in tabs" :key="tab.id" :aria-current="m.tab===tab.id?'page':undefined" @click="changeTab(tab.id)">{{ tab.label }}</button></nav>
  <p v-if="error" class="v2-error" role="alert">{{ error }}<button class="v2-link" @click="reload">Riprova caricamento</button></p>
  <div v-if="loading" role="status" class="v2-skeleton" aria-label="Caricamento marketing"></div>
  <template v-else>
   <V2Panel v-if="m.tab==='audience'" title="La tua audience" description="Profili dei tifosi e consenso per le comunicazioni."><div class="v2-toolbar" style="margin-bottom:20px"><label class="v2-field">Cerca un tifoso<input v-model="m.q" type="search" placeholder="Nickname o telefono" /></label><span class="v2-badge">{{ m.audience.length }} risultati</span></div><div v-if="m.audience.length" class="v2-table-wrap"><table class="v2-table"><thead><tr><th>Tifoso</th><th>Telefono</th><th>Registrazione</th><th>Ultima attività</th><th>Monete</th><th>Consenso marketing</th></tr></thead><tbody><tr v-for="fan in m.audience" :key="fan.fan_id"><td><button class="v2-link" @click="m.selectedFan=fan">{{ fan.nickname }}</button></td><td>{{ m.maskPhone(fan.phone) }}</td><td>{{ fan.created_at }}</td><td>{{ fan.last_seen_at || '—' }}</td><td>{{ fan.coins }}</td><td><span class="v2-badge" :class="fan.marketing_consent?'success':''">{{ fan.marketing_consent?'Presente':'Assente' }}</span></td></tr></tbody></table></div><p v-else class="v2-empty">Nessun tifoso trovato con questa ricerca.</p></V2Panel>
   <template v-else-if="m.tab==='campaigns'"><div class="v2-grid-3"><article class="v2-metric"><span>Costo per SMS</span><strong>€ {{ money(m.billing.sms_cost) }}</strong><small>Tariffa della società</small></article><article class="v2-metric"><span>SMS gratuiti disponibili</span><strong>{{ m.billing.free_sms_remaining }}</strong></article><article class="v2-metric"><span>Costo stimato della campagna</span><strong>€ {{ money(m.estimatedCost) }}</strong><small>{{ m.selectedCampaignAudience.length }} destinatari selezionati</small></article></div><V2Panel title="Prepara una campagna" description="I filtri sono cumulabili e includono solo tifosi con consenso marketing."><form class="v2-stack" @submit.prevent="c.confirmAction('Programmare la campagna?',`La campagna contiene ${m.selectedCampaignAudience.length} destinatari. Il costo stimato è € ${money(m.estimatedCost)}.`,()=>c.run('campaign-create',m.createCampaign,'Campagna programmata.'))"><label class="v2-field">Nome della campagna<input v-model="m.campaign.name" required placeholder="Nome della campagna" /></label><label class="v2-field">Messaggio SMS<textarea v-model="m.campaign.message" required rows="4" placeholder="Scrivi il messaggio per i tifosi…"></textarea></label><fieldset><legend>Seleziona i destinatari</legend><div class="v2-grid-3"><label v-for="filter in filters" :key="filter.id" class="v2-check"><input v-model="m.campaignFilters[filter.id]" type="checkbox" />{{ filter.label }}</label></div></fieldset><details><summary>Destinatari inclusi · {{ m.selectedCampaignAudience.length }}</summary><p v-if="!m.selectedCampaignAudience.length" class="v2-muted">Nessun tifoso corrisponde ai filtri.</p><ul v-else class="v2-audience-list"><li v-for="fan in m.selectedCampaignAudience" :key="fan.fan_id"><strong>{{ fan.nickname }}</strong><span>{{ m.maskPhone(fan.phone) }}</span><span>{{ fan.coins }} monete</span></li></ul></details><div class="v2-toolbar"><button class="v2-button v2-primary" type="submit" :disabled="c.busy('campaign-create')">Programma campagna</button><button class="v2-button" type="button" :disabled="!m.campaign.id||c.busy('campaign-send')" @click="c.confirmAction('Inviare gli SMS adesso?', 'L’invio genera messaggi reali ai destinatari della campagna salvata e può comportare addebiti.',()=>c.run('campaign-send',m.sendNow,'Invio della campagna richiesto.'))">Invia ora</button><button class="v2-button" type="button" :disabled="!m.campaign.id||c.busy('campaign-test')" @click="c.run('campaign-test',m.sendTest)">Invia test</button><span v-if="m.campaign.id" class="v2-badge">Campagna #{{ m.campaign.id }}</span></div><small>Programma la campagna per abilitare l’invio immediato o il test. Il test chiede il numero di destinazione e invia un SMS reale.</small></form></V2Panel></template>
   <V2Panel v-else-if="m.tab==='templates'" title="Template dei messaggi" description="Prepara i testi da riutilizzare nelle comunicazioni."><form class="v2-stack" @submit.prevent="c.run('template-save',m.saveTemplate,'Template salvato.')"><div class="v2-grid-2"><label class="v2-field">Nome del template<input v-model="m.templateDraft.name" required /></label><label class="v2-field">Categoria<select v-model="m.templateDraft.category"><option v-for="category in m.categories" :key="category" :value="category">{{ category }}</option></select></label></div><label class="v2-field">Testo del messaggio<textarea v-model="m.templateDraft.body" required rows="4"></textarea></label><div><button class="v2-button v2-primary" :disabled="c.busy('template-save')">Salva template</button></div></form><hr class="v2-divider" /><div v-if="m.templates.length" class="v2-stack"><article v-for="template in m.templates" :key="template.id" class="v2-template-row"><div><h3>{{ template.name }}</h3><small>{{ template.category }}</small><p class="v2-muted">{{ template.body }}</p></div><button class="v2-button v2-danger" :disabled="c.busy(`template-${template.id}`)" @click="c.confirmAction('Eliminare il template?',`Verrà rimosso il template “${template.name}”.`,()=>c.run(`template-${template.id}`,()=>m.removeTemplate(template.id),'Template eliminato.'))">Elimina</button></article></div><p v-else class="v2-empty">Nessun template salvato.</p></V2Panel>
   <template v-else><div class="v2-grid-4"><article v-for="metric in billingMetrics" :key="metric.label" class="v2-metric"><span>{{ metric.label }}</span><strong>{{ metric.value }}</strong></article></div><V2Panel title="Registro invii" description="Esiti e addebiti delle comunicazioni della società."><template #actions><button class="v2-button" :disabled="c.busy('marketing-logs')" @click="c.run('marketing-logs',m.loadLogs)">Aggiorna</button></template><div v-if="m.logs.length" class="v2-table-wrap"><table class="v2-table"><thead><tr><th>ID</th><th>Telefono</th><th>Stato</th><th>Costo</th><th>Errore</th><th>Creato il</th></tr></thead><tbody><tr v-for="log in m.logs" :key="log.id"><td>#{{ log.id }}</td><td>{{ m.maskPhone(log.phone) }}</td><td><span class="v2-badge">{{ log.status }}</span></td><td>€ {{ money(log.sms_cost_charged) }} <span v-if="log.used_free_sms" class="v2-badge success">Gratuito</span></td><td>{{ log.error || '—' }}</td><td>{{ log.created_at }}</td></tr></tbody></table></div><p v-else class="v2-empty">Non ci sono ancora invii nel registro.</p></V2Panel></template>
  </template>
  <V2Dialog :open="!!m.selectedFan" :title="m.selectedFan?.nickname || 'Dettaglio tifoso'" @close="m.selectedFan=null"><template v-if="m.selectedFan"><p>{{ m.selectedFan.phone }}</p><span class="v2-badge" :class="m.selectedFan.marketing_consent?'success':'warning'">{{ m.selectedFan.marketing_consent?'Consenso marketing presente':'Consenso marketing assente' }}</span><form class="v2-stack" @submit.prevent="c.run('single-sms',m.sendSingle,'Richiesta di invio SMS completata.')"><label class="v2-field">Messaggio personale<textarea v-model="m.singleMessage" required rows="4" placeholder="Scrivi il messaggio…"></textarea></label><button class="v2-button v2-primary" :disabled="!m.selectedFan.marketing_consent || c.busy('single-sms')">Invia SMS</button><small>Invia un SMS reale a questo tifoso.</small></form></template></V2Dialog>
 </div>
</template>
<script setup>
import { computed, inject, proxyRefs, ref } from 'vue';
import { useController } from '../../components/admin/marketing/MarketingSection.vue?admin-v2-controller';
import V2Panel from '../components/shared/V2Panel.vue';
import V2Dialog from '../components/shared/V2Dialog.vue';
const c=inject('admin-v2');const loading=ref(true),error=ref('');
const m=proxyRefs(useController({},()=>{},{onLifecycleComplete(){loading.value=false;},onLifecycleError(e){error.value=e?.response?.data?.message||'Impossibile caricare i dati marketing.';loading.value=false;}}));
const tabs=[{id:'audience',label:'Audience'},{id:'campaigns',label:'Campagne SMS'},{id:'templates',label:'Template'},{id:'logs',label:'Registro e costi'}];
const filters=[{id:'male',label:'Uomo'},{id:'female',label:'Donna'},{id:'newUsers',label:'Nuovi utenti dell’ultimo evento'},{id:'nonZeroCoins',label:'Saldo monete diverso da zero'},{id:'topCoins',label:'Saldo monete più alto'}];
const money=value=>Number(value||0).toFixed(2);
const billingMetrics=computed(()=>[{label:'Costo per SMS',value:`€ ${money(m.billing.sms_cost)}`},{label:'SMS gratuiti rimasti',value:m.billing.free_sms_remaining},{label:'SMS totali',value:m.billing.total_messages},{label:'Totale addebitato',value:`€ ${money(m.billing.total_cost_charged)}`}]);
function changeTab(tab){m.tab=tab;}
async function reload(){loading.value=true;error.value='';try{await Promise.all([m.loadAudience(),m.loadTemplates(),m.loadBilling(),m.loadLogs()]);}catch(e){error.value=e?.response?.data?.message||'Impossibile caricare i dati marketing.';}finally{loading.value=false;}}
</script>
<style scoped>.v2-audience-list{list-style:none;padding:0;margin:0;max-height:250px;overflow:auto}.v2-audience-list li{display:flex;align-items:center;gap:16px;flex-wrap:wrap;border-bottom:1px solid var(--v2-line);padding:10px 0;font-size:12px}.v2-audience-list li strong{flex:1}.v2-template-row{display:flex;justify-content:space-between;align-items:flex-start;gap:18px;border-bottom:1px solid var(--v2-line);padding-bottom:20px}.v2-template-row p{margin-top:10px;font-size:13px;white-space:pre-wrap}@media(max-width:640px){.v2-template-row{display:grid}}</style>
